<script setup lang="ts">
import {ArrowUpRight,ShieldCheck} from 'lucide-vue-next'
import {safeUrl} from '../api'
import type {Explain,Source} from '../types'
const props=defineProps<{explanation:Explain;sources:Source[]}>()
function sourceFor(id:string){return props.sources.find(source=>source.id===id)}
</script>
<template><div v-if="explanation?.content" class="ai-content"><p class="evidence-note"><ShieldCheck :size="14"/>{{explanation.cached?'读取已缓存解释':'基于当前来源生成'}} · 引用有效不代表每句话都已核实，请结合原始来源判断。</p><div v-for="part in [{title:'这是什么',text:explanation.content.overview},{title:'核心原理',text:explanation.content.principle},{title:'一个例子',text:explanation.content.example},{title:'背景与来路',text:explanation.content.background}]" :key="part.title" class="explanation-part"><template v-if="part.text"><h3>{{part.title}}</h3><p>{{part.text}}</p></template></div><div v-if="explanation.content.analogy" class="analogy-note"><span class="tiny-label">教学类比 · 帮助理解</span><p>{{explanation.content.analogy.text}}</p><small>适用边界：{{explanation.content.analogy.limits}}</small></div><div v-for="part in [{title:'真实应用',list:explanation.content.applications},{title:'常见误解',list:explanation.content.misconceptions},{title:'前沿与开放问题',list:explanation.content.open_questions}]" :key="part.title" class="explanation-part"><template v-if="part.list?.length"><h3>{{part.title}}</h3><ul><li v-for="(line,i) in part.list" :key="i">{{line}}</li></ul></template></div><p v-if="!explanation.content.open_questions?.length" class="muted">现有资料不足以支持前沿或开放问题，暂不扩展。</p><div v-if="explanation.content.claims?.length" class="claims"><h3>关键陈述与引用</h3><div v-for="(claim,i) in explanation.content.claims" :key="i" class="claim"><span class="claim-type">{{claim.kind==='fact'?'事实说明':claim.kind==='analogy'?'教学类比':'待核实'}}</span><p>{{claim.text}}</p><small v-if="claim.support_status">{{claim.support_status==='teaching_analogy'?'教学类比':'引用位置已检查，陈述支持性仍需核对'}}</small><blockquote v-for="(ref,j) in claim.evidence_refs||[]" :key="j" class="located-quote">{{ref.quote}}</blockquote><template v-for="sid in claim.source_ids" :key="sid"><a v-if="sourceFor(sid)" :href="safeUrl(sourceFor(sid)?.url)" target="_blank" rel="noopener noreferrer" class="source-chip">{{sourceFor(sid)?.platform}} [{{sid}}]<ArrowUpRight :size="11"/></a></template></div></div><div v-if="explanation.content.questions?.length" class="thinking-questions"><span class="tiny-label">THINK A LITTLE FURTHER</span><h3>带着问题再往前一步</h3><p v-for="(question,i) in explanation.content.questions" :key="i">0{{i+1}} — {{question}}</p></div><p class="usage-note" v-if="explanation.usage">供应商 usage：输入 {{explanation.usage.input_tokens??'未知'}} / 输出 {{explanation.usage.output_tokens??'未知'}} Token · 未配置价格不估算费用</p></div></template>
